'use strict';
/* public/js/95-pause.js -- pause menu, settings, key rebinding; then the final session resume and debug exports (must stay last). Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---------- pause menu ---------- */
/* =====================================================================
   PAUSE MENU  (Escape opens/closes it; Resume, Options, Controls, Restart, Quit)
   Everything the feature owns lives in this one section. Only a handful of one-line
   hooks sit elsewhere: uiOpen() (so movement/digging/water-drain pause), the
   keydown/keyup handlers (Escape + the key-remap layer), releaseLock() and the
   pointerlockchange listener (so losing pointer lock via Escape also opens this),
   the mouse/touch look code (sensitivity + invert Y), perfTick (fixed render quality),
   initAudio/noise/tone/startMusic (an Effects bus separate from Music), and one line
   in startGame() (apply saved volumes once the audio graph exists).
   ===================================================================== */

/* ---- rebindable actions: id, label shown in the UI, and the default physical key.
   Movement (forward/back/left/right) always ALSO answers to WASD and the arrow keys,
   no matter what they're rebound to -- see the "fixed alternative" note in rebuildRemap(). */
const BIND_DEFS=[
  {id:'forward',label:'Move forward',def:'w'},{id:'back',label:'Move back',def:'s'},
  {id:'left',label:'Move left',def:'a'},{id:'right',label:'Move right',def:'d'},
  {id:'sprint',label:'Sprint',def:'shift'},{id:'jump',label:'Jump / climb out of a hole',def:' '},
  {id:'dig',label:'Dig (hold)',def:'e'},{id:'use',label:'Use / talk / buy / sell',def:'f'},
  {id:'onion',label:'Eat an onion',def:'q'},{id:'detector',label:'Toggle the detector',def:'t'},
  {id:'sound',label:'Mute sound',def:'m'},{id:'firstPerson',label:'First / third person',def:'v'},
  {id:'crouch',label:'Crouch',def:'c'},{id:'ping',label:'Ping the map',def:'g'},
  {id:'flashlight',label:'Flashlight',def:'l'},{id:'chat',label:'Open chat',def:'enter'},
  {id:'shout1',label:'Shout 1',def:'1'},{id:'shout2',label:'Shout 2',def:'2'},
  {id:'shout3',label:'Shout 3',def:'3'},{id:'shout4',label:'Shout 4',def:'4'},{id:'shout5',label:'Shout 5',def:'5'},
  {id:'pushtalk',label:'Push to talk (voice)',def:'p'},{id:'grab',label:'Grab (hold)',def:'r'},{id:'rope',label:'Tie / untie your rope',def:'x'},{id:'twerk',label:'Twerk',def:'b'},{id:'sing',label:'Sing the lullaby (hold)',def:'h'},{id:'inventory',label:'Inventory',def:'i'},
];
const RESERVED_KEYS=new Set(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright','escape','`']);
const KEY_NAMES={' ':'Space','arrowup':'Up','arrowdown':'Down','arrowleft':'Left','arrowright':'Right','enter':'Enter','shift':'Shift','`':'`'};
const keyLabel=k=>KEY_NAMES[k]||(k.length===1?k.toUpperCase():k);
const defaultBinds=()=>Object.fromEntries(BIND_DEFS.map(b=>[b.id,b.def]));

/* ---- settings: one blob in localStorage, loaded once and applied everywhere it matters. ---- */
const SETTINGS_KEY='cgl-settings';
const SETTINGS={sens:1,invertY:false,touchSens:1,fov:62,volMaster:0.55,volFx:1,volMusic:1,volVoice:1,
  shadows:true,quality:'auto',showFps:false,mapStyle:'square',mapScale:1,mapOpacity:1,binds:defaultBinds()};
function loadSettings(){
  try{
    const o=JSON.parse(localStorage.getItem(SETTINGS_KEY)||'null');if(!o||typeof o!=='object')return;
    for(const k of['sens','touchSens','fov','volMaster','volFx','volMusic','volVoice'])if(Number.isFinite(o[k]))SETTINGS[k]=o[k];
    if(typeof o.invertY==='boolean')SETTINGS.invertY=o.invertY;
    if(typeof o.shadows==='boolean')SETTINGS.shadows=o.shadows;
    if(typeof o.showFps==='boolean')SETTINGS.showFps=o.showFps;
    if(['auto','low','med','high'].includes(o.quality))SETTINGS.quality=o.quality;
    if(['square','compass'].includes(o.mapStyle))SETTINGS.mapStyle=o.mapStyle;
    if(Number.isFinite(o.mapScale))SETTINGS.mapScale=clamp(o.mapScale,0.6,1.6);
    if(Number.isFinite(o.mapOpacity))SETTINGS.mapOpacity=clamp(o.mapOpacity,0.2,1);
    if(o.binds&&typeof o.binds==='object')for(const b of BIND_DEFS)if(typeof o.binds[b.id]==='string')SETTINGS.binds[b.id]=o.binds[b.id];
    if(SETTINGS.binds.pushtalk==='b')SETTINGS.binds.pushtalk='p';   // push-to-talk moved B -> P (B is Greg's twerk emote); saved settings from before still said b
  }catch(e){}
}
function saveSettings(){try{localStorage.setItem(SETTINGS_KEY,JSON.stringify(SETTINGS))}catch(e){}}

/* ---- key remap layer: turns whatever key is physically pressed into the default key name the rest
   of the file already checks (KEYS['w'], k==='e', ...), so none of that code had to change. Rebuilt
   whenever a binding changes. Returns null for a key that isn't bound to anything right now. */
let REMAP=Object.create(null);
function rebuildRemap(){
  REMAP=Object.create(null);
  for(const k of['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'])REMAP[k]=k;   // fixed alternative: always movement
  for(const b of BIND_DEFS)REMAP[SETTINGS.binds[b.id]]=b.def;
}
const remapKey=pk=>REMAP[pk]||null;

/* ---- apply settings to the live game ---- */
let fxBus=null;
function applyVolume(){
  if(master)master.gain.value=muted?0:SETTINGS.volMaster;
  if(fxBus)fxBus.gain.value=SETTINGS.volFx;
  if(partyBus)partyBus.gain.value=0.85*SETTINGS.volMusic;
  if(voiceMaster)voiceMaster.gain.value=(VOX.muted?0:1)*SETTINGS.volVoice;
}
function applyFov(){camera.fov=SETTINGS.fov;camera.updateProjectionMatrix()}
function applyShadows(){renderer.shadowMap.enabled=SETTINGS.shadows}
const QUALITY_PR={low:0.65,med:1,high:MAX_PR};
function applyQuality(){
  if(SETTINGS.quality==='auto')return;   // perfTick's adaptive step takes it from here
  const pr=QUALITY_PR[SETTINGS.quality]||MAX_PR;
  PERF.pr=pr;renderer.setPixelRatio(pr);renderer.setSize(innerWidth,innerHeight);
}
function applyFpsVisibility(){if(PERF.el)PERF.el.hidden=!(SETTINGS.showFps||/fps/.test(location.hash))}
/* minimap size + opacity (Options > Minimap): CSS variables on the map panel, so both map styles and the zoom/field-map
   buttons scale together from the top-right corner. The J field map moves the canvas out, so it isn't affected. */
function applyMapLook(){const m=$('#mapbox');m.style.setProperty('--map-scale',SETTINGS.mapScale);m.style.setProperty('--map-opacity',SETTINGS.mapOpacity)}
function applySettings(){rebuildRemap();applyVolume();applyFov();applyShadows();applyQuality();applyFpsVisibility();setMapStyle(SETTINGS.mapStyle);applyMapLook()}

/* ---- pause state + screens ---- */
const PAUSE={open:false};
let voluntaryRelease=false;
const pauseEl=$('#pause'),pMain=$('#pMain'),pOptionsCard=$('#pOptionsCard'),pControlsCard=$('#pControlsCard'),pConfirmCard=$('#pConfirmCard');
function overlayBlocking(){return uiOpen()||!$('#admin').hidden||!$('#win').hidden}
function tryLock(){lockMouse()}
function showPauseScreen(name){
  stopListening();
  pMain.hidden=name!=='main';pOptionsCard.hidden=name!=='options';pControlsCard.hidden=name!=='controls';pConfirmCard.hidden=name!=='confirm';
}
function openPause(){
  if(PAUSE.open||!S.started)return;
  PAUSE.open=true;digHeld=false;releaseLock();
  showPauseScreen('main');pauseEl.hidden=false;
}
function closePause(){
  if(!PAUSE.open)return;
  PAUSE.open=false;pauseEl.hidden=true;tryLock();
}
$('#tPause').onclick=()=>{if(S.started&&!overlayBlocking())openPause()};
if(isTouch)$('#tPause').hidden=false;
$('#pResume').onclick=closePause;
$('#pOptions').onclick=()=>{renderOptions();showPauseScreen('options')};
$('#pOptBack').onclick=()=>showPauseScreen('main');
$('#pControlsBtn').onclick=()=>{renderControlsList();showPauseScreen('controls')};
$('#pCtrlBack').onclick=()=>showPauseScreen('main');
function askConfirm(title,text,yesLabel,onYes){
  $('#pConfirmTitle').textContent=title;$('#pConfirmText').textContent=text;
  const yes=$('#pConfirmYes');yes.textContent=yesLabel;yes.onclick=onYes;
  $('#pConfirmNo').onclick=()=>showPauseScreen('main');
  showPauseScreen('confirm');
}
$('#pRestart').onclick=()=>askConfirm('Restart?',
  'This respawns you at camp: full health and water, and out of any hole you were stuck in. It does NOT reset your seeds, gear, sack, onions, the team\'s quota, or the time of day -- that\'s shared with everyone at camp and already saved.',
  'Respawn at camp',()=>{logEv('pause',{action:'restart'});respawn();closePause()});
$('#pQuit').onclick=()=>askConfirm('Quit to title?',
  'Your progress is saved. You\'ll disconnect from camp and land back on the title screen -- come back any time to pick up where you left off.',
  'Quit to title',quitToTitle);
function quitToTitle(){
  logEv('pause',{action:'quit'});flushLog();   // send this before the socket closes: nothing left in the queue survives a reload
  saveSession();
  S.started=false;   // the existing pagehide listener also calls saveSession(); without this it would re-write the session we're about to clear
  try{sessionStorage.removeItem('cgl-session')}catch(e){}   // so the reload lands on the title screen instead of auto-resuming
  if(net.ws)try{net.ws.close()}catch(e){}
  location.reload();
}

/* ---- options screen ---- */
const oSens=$('#oSens'),oSensV=$('#oSensV'),oInvert=$('#oInvert'),oTouchSens=$('#oTouchSens'),oTouchSensV=$('#oTouchSensV'),oMapScale=$('#oMapScale'),oMapScaleV=$('#oMapScaleV'),oMapOpacity=$('#oMapOpacity'),oMapOpacityV=$('#oMapOpacityV'),
      oFov=$('#oFov'),oFovV=$('#oFovV'),oVolMaster=$('#oVolMaster'),oVolMasterV=$('#oVolMasterV'),
      oVolFx=$('#oVolFx'),oVolFxV=$('#oVolFxV'),oVolMusic=$('#oVolMusic'),oVolMusicV=$('#oVolMusicV'),
      oVolVoice=$('#oVolVoice'),oVolVoiceV=$('#oVolVoiceV'),
      oShadows=$('#oShadows'),oFps=$('#oFps'),oQuality=$('#oQuality'),oMapStyle=$('#oMapStyle');
function renderOptions(){
  oSens.value=SETTINGS.sens;oSensV.textContent=SETTINGS.sens.toFixed(2)+'x';
  oMapScale.value=SETTINGS.mapScale;oMapScaleV.textContent=Math.round(SETTINGS.mapScale*100)+'%';
  oMapOpacity.value=Math.round(SETTINGS.mapOpacity*100);oMapOpacityV.textContent=Math.round(SETTINGS.mapOpacity*100)+'%';
  oInvert.checked=SETTINGS.invertY;
  oTouchSens.value=SETTINGS.touchSens;oTouchSensV.textContent=SETTINGS.touchSens.toFixed(2)+'x';
  oFov.value=SETTINGS.fov;oFovV.textContent=SETTINGS.fov+'°';
  oVolMaster.value=Math.round(SETTINGS.volMaster*100);oVolMasterV.textContent=oVolMaster.value+'%';
  oVolFx.value=Math.round(SETTINGS.volFx*100);oVolFxV.textContent=oVolFx.value+'%';
  oVolMusic.value=Math.round(SETTINGS.volMusic*100);oVolMusicV.textContent=oVolMusic.value+'%';
  oVolVoice.value=Math.round(SETTINGS.volVoice*100);oVolVoiceV.textContent=oVolVoice.value+'%';
  oShadows.checked=SETTINGS.shadows;oFps.checked=SETTINGS.showFps;
  for(const b of oQuality.children)b.setAttribute('aria-pressed',b.dataset.v===SETTINGS.quality?'true':'false');
  for(const b of oMapStyle.children)b.setAttribute('aria-pressed',b.dataset.v===SETTINGS.mapStyle?'true':'false');
  renderBindList();
}
oMapScale.oninput=()=>{SETTINGS.mapScale=+oMapScale.value;oMapScaleV.textContent=Math.round(SETTINGS.mapScale*100)+'%';applyMapLook();saveSettings()};
oMapOpacity.oninput=()=>{SETTINGS.mapOpacity=+oMapOpacity.value/100;oMapOpacityV.textContent=oMapOpacity.value+'%';applyMapLook();saveSettings()};
oSens.oninput=()=>{SETTINGS.sens=+oSens.value;oSensV.textContent=SETTINGS.sens.toFixed(2)+'x';saveSettings()};
oInvert.onchange=()=>{SETTINGS.invertY=oInvert.checked;saveSettings()};
oTouchSens.oninput=()=>{SETTINGS.touchSens=+oTouchSens.value;oTouchSensV.textContent=SETTINGS.touchSens.toFixed(2)+'x';saveSettings()};
oFov.oninput=()=>{SETTINGS.fov=+oFov.value;oFovV.textContent=SETTINGS.fov+'°';applyFov();saveSettings()};
oVolMaster.oninput=()=>{SETTINGS.volMaster=+oVolMaster.value/100;oVolMasterV.textContent=oVolMaster.value+'%';applyVolume();saveSettings()};
oVolFx.oninput=()=>{SETTINGS.volFx=+oVolFx.value/100;oVolFxV.textContent=oVolFx.value+'%';applyVolume();saveSettings()};
oVolMusic.oninput=()=>{SETTINGS.volMusic=+oVolMusic.value/100;oVolMusicV.textContent=oVolMusic.value+'%';applyVolume();saveSettings()};
oVolVoice.oninput=()=>{SETTINGS.volVoice=+oVolVoice.value/100;oVolVoiceV.textContent=oVolVoice.value+'%';applyVolume();saveSettings()};
oShadows.onchange=()=>{SETTINGS.shadows=oShadows.checked;applyShadows();saveSettings()};
oMapStyle.onclick=e=>{const b=e.target.closest('button');if(!b)return;SETTINGS.mapStyle=b.dataset.v;for(const c of oMapStyle.children)c.setAttribute('aria-pressed',c===b?'true':'false');setMapStyle(SETTINGS.mapStyle);saveSettings()};
oFps.onchange=()=>{SETTINGS.showFps=oFps.checked;applyFpsVisibility();saveSettings()};
oQuality.onclick=e=>{const b=e.target.closest('button');if(!b)return;SETTINGS.quality=b.dataset.v;for(const c of oQuality.children)c.setAttribute('aria-pressed',c===b?'true':'false');applyQuality();saveSettings()};

/* ---- key-binding capture: click a row, press a key. Conflicts get a warning but aren't blocked;
   the fixed keys (WASD, arrows, Escape, `) can't be reassigned at all. ---- */
const bindListEl=$('#bindList'),bindWarnEl=$('#bindWarn');
let listeningFor=null,cancelListen=null;
function stopListening(){if(cancelListen){document.removeEventListener('keydown',cancelListen,true);cancelListen=null}listeningFor=null}
function conflictFor(id,key){for(const b of BIND_DEFS)if(b.id!==id&&SETTINGS.binds[b.id]===key)return b.label;return null}
function renderBindList(){
  stopListening();bindListEl.textContent='';bindWarnEl.hidden=true;
  for(const b of BIND_DEFS){
    const row=document.createElement('div');row.className='bindrow';
    const span=document.createElement('span');span.textContent=b.label;
    const btn=document.createElement('button');btn.type='button';btn.className='keybtn';
    btn.textContent=keyLabel(SETTINGS.binds[b.id]);
    btn.onclick=()=>startListening(b.id,btn);
    row.append(span,btn);bindListEl.appendChild(row);
  }
}
function startListening(id,btn){
  if(listeningFor)return;   // one capture at a time
  listeningFor=id;btn.classList.add('listening');btn.textContent='Press a key…';bindWarnEl.hidden=true;
  cancelListen=e=>{
    e.preventDefault();e.stopPropagation();
    const key=e.key.toLowerCase();
    stopListening();
    if(key==='escape'){renderBindList();return}   // cancel, keep the old binding
    if(RESERVED_KEYS.has(key)){bindWarnEl.hidden=false;bindWarnEl.textContent=`${keyLabel(key)} is fixed and can't be reassigned.`;renderBindList();return}
    const clash=conflictFor(id,key);
    SETTINGS.binds[id]=key;rebuildRemap();saveSettings();
    for(const kk in KEYS)KEYS[kk]=false;digHeld=false;   // a rebind mid-hold shouldn't leave a key stuck "on"
    renderBindList();
    if(clash){bindWarnEl.hidden=false;bindWarnEl.textContent=`Heads up: that key was already "${clash}". It now does both.`}
  };
  document.addEventListener('keydown',cancelListen,true);
}
$('#bindReset').onclick=()=>{Object.assign(SETTINGS.binds,defaultBinds());rebuildRemap();saveSettings();renderBindList()};
addEventListener('blur',stopListening);

/* ---- controls screen: one row per action, reading the *current* binding ---- */
const pControlsListEl=$('#pControlsList');
function renderControlsList(){
  pControlsListEl.textContent='';
  let shownShout=false;
  for(const b of BIND_DEFS){
    if(b.id.startsWith('shout')){
      if(shownShout)continue;shownShout=true;
      const div=document.createElement('div');
      div.innerHTML=BIND_DEFS.filter(d=>d.id.startsWith('shout')).map(d=>`<kbd>${keyLabel(SETTINGS.binds[d.id])}</kbd>`).join('')+' Shout 1-5';
      pControlsListEl.appendChild(div);continue;
    }
    const div=document.createElement('div');
    div.innerHTML=`<kbd>${keyLabel(SETTINGS.binds[b.id])}</kbd> ${b.label}`;
    pControlsListEl.appendChild(div);
  }
  const note=document.createElement('div');note.style.cssText='grid-column:1/-1;color:var(--ink-soft);font-size:13px;padding-top:6px';
  note.textContent='Click the game to lock the mouse and look around. WASD and the arrow keys always move you too, even when rebound.';
  pControlsListEl.appendChild(note);
}

loadSettings();
applySettings();

